c       = 299792458;          % speed of light [m/s]
Re      = 6371e3;             % mean Earth radius (spherical Earth) [m]
omegaE  = 7.2921151467e-5;    % Earth rotation rate [rad/s]
mu      = 3.986004418e14;     % Earth gravitational parameter [m^3/s^2]
Rorb    = 26560e3;            % GPS orbit radius [m]
inc     = deg2rad(55);        % GPS orbital inclination
 
% 24 satellites: 6 planes x 4 satellites (simplified Walker-like layout)
