orb.R   = Rorb;  orb.inc = inc;
orb.n   = sqrt(mu/Rorb^3);                 % mean motion [rad/s]
orb.Omega = zeros(1,N);  orb.u0 = zeros(1,N);
for k = 1:nPlanes
    for j = 1:nPer
