%% ========================================================================
%  SECTION 6 - SIMULATION LOGIC (callbacks, main loop, single time step)
%  ========================================================================
    function onStart(~,~)                 % Start / Pause toggle
        if running
            running = false;  set(btnStart,'String','Start');
        else
            running = true;   set(btnStart,'String','Pause');
            while running && ishandle(fig)    % real-time animation loop
                stepSim();
                drawnow limitrate;
                pause(0.02);
            end
        end
    end
 
    function onReset(~,~)                 % Reset time, user position and plots
        resetState();  drawFrame();
    end
 
    function onClose(~,~)                 % Stop loop safely before closing
        running = false;  delete(fig);
    end
 
    function onSelectDoc(src,~)           % Show selected function description
        set(funText,'String',cellstr(docs(src.Value).text));
    end
 
    function resetState()
        simT = 0;  lat = deg2rad(30);  lon = deg2rad(100);   % start point (editable)
        tHist(:) = NaN;  eHist(:) = NaN;  dHist(:) = NaN;  trail(:) = NaN;
    end
 
    function stepSim()                    % ONE simulation step
        dt   = get(sWarp,'Value');        % simulated seconds per frame
        simT = simT + dt;
        % --- user motion on the sphere (constant speed and heading)
        v  = get(sSpeed,'Value');  az = deg2rad(get(sHead,'Value'));
        lat = lat + v*dt*cos(az)/Re;
        lat = max(min(lat,deg2rad(80)),-deg2rad(80));
        lon = lon + v*dt*sin(az)/(Re*cos(lat));
        drawFrame();
    end
 
    function drawFrame()                  % compute GPS solution + update graphics
        sigma = get(sNoise,'Value');  biasM = c*1e-6*get(sBias,'Value');
        mask  = get(sMask,'Value');
 
        ru = Re*[cos(lat)*cos(lon); cos(lat)*sin(lon); sin(lat)];   % true user ECEF
        S  = satECEF(simT,orb);                                      % 3xN satellite ECEF
        [vis,el] = visibility(S,ru,mask);                            %#ok<ASGLU>
 
        % --- satellites and labels
        set(hSatVis,'XData',S(1,vis)/1e3,'YData',S(2,vis)/1e3,'ZData',S(3,vis)/1e3);
        set(hSatHid,'XData',S(1,~vis)/1e3,'YData',S(2,~vis)/1e3,'ZData',S(3,~vis)/1e3);
        for i = 1:N
            set(hLbl(i),'Position',S(:,i)'/1e3);
        end
 
        % --- true-path trail
        trail = [trail(:,2:end), ru/1e3];
        set(hTrail,'XData',trail(1,:),'YData',trail(2,:),'ZData',trail(3,:));
        set(hUser,'XData',ru(1)/1e3,'YData',ru(2)/1e3,'ZData',ru(3)/1e3);
 
        % --- pseudorange lines (only to visible satellites)
        for i = 1:N
            if vis(i)
                set(hLine(i),'Visible','on','XData',[ru(1) S(1,i)]/1e3, ...
                    'YData',[ru(2) S(2,i)]/1e3,'ZData',[ru(3) S(3,i)]/1e3);
            else
                set(hLine(i),'Visible','off');
            end
        end
 
        % --- measurements and position solution
        nv = nnz(vis);
        if nv >= 4
            rho = pseudoranges(S(:,vis),ru,biasM,sigma);             % measurements
            [xhat,Q] = solveGPS(S(:,vis),rho);                       % least squares
            pEst = xhat(1:3);
            err  = pEst - ru;
            R    = ecef2enuRot(lat,lon);   enu = R*err;
            err3 = norm(err);
            pdop = sqrt(Q(1,1)+Q(2,2)+Q(3,3));
            set(hEst,'XData',pEst(1)/1e3,'YData',pEst(2)/1e3,'ZData',pEst(3)/1e3);
            latE = asind(pEst(3)/norm(pEst));  lonE = atan2d(pEst(2),pEst(1));
            txt = { sprintf('Time %7.1f min   Visible satellites: %d / %d',simT/60,nv,N), ...
                    sprintf('True  lat/lon : %9.4f, %9.4f deg',rad2deg(lat),rad2deg(lon)), ...
                    sprintf('Est.  lat/lon : %9.4f, %9.4f deg',latE,lonE), ...
                    sprintf('Error E/N/U   : %7.2f %7.2f %7.2f m  (3D %.2f m)',enu,err3), ...
                    sprintf('Clock bias    : est %.1f us / true %.1f us    PDOP %.2f',xhat(4)/c*1e6,biasM/c*1e6,pdop) };
        else
            err3 = NaN;  pdop = NaN;  set(hEst,'XData',NaN,'YData',NaN,'ZData',NaN);
            txt = { sprintf('Time %7.1f min   Visible satellites: %d / %d',simT/60,nv,N), ...
                    'Fewer than 4 satellites visible: no position fix.' };
        end
        set(readout,'String',txt);
 
        % --- error and PDOP history
        tHist = [tHist(2:end), simT/60];  eHist = [eHist(2:end), err3];  dHist = [dHist(2:end), pdop];
        set(hErr,'XData',tHist,'YData',eHist);
        set(hDop,'XData',tHist,'YData',dHist);
    end
 
